  video: ['mp4', 'mov', 'mkv', 'webm', 'avi', 'm4v', '3gp'],
  audio: ['mp3', 'wav', 'm4a', 'aac', 'ogg', 'opus', 'flac'],
  image: ['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp'],
  subtitle: ['srt', 'vtt', 'ass'],
